# -*- coding: utf-8 -*-
"""Allotting shares, assigning qualities, and tribal institutions."""
import json
from pathlib import Path
from lesson_authoring import entry as E
TR=[['拉丁 tribus','罗马的社会、政治分组；更早来源未完全确定']]
T=[['拉丁 tribuere','分派、给予、支付；传统词源常联系 tribus“群体、部族”']]
D=T+[['拉丁 dis- + tribuere → distribuere / distribūtus','分开给予 → 分配'],['英语 distribute','分发、配送、分布']]
AT=T+[['拉丁 ad- + tribuere → attribuere / attribūtus','分派给、归于'],['英语 attribute','动词归于；名词属性']]
TB=T+[['拉丁 tribūtum → 法语 tribut → 英语 tribute','所支付、献出的东西 → 贡赋；致敬']]
def A(h,a,b):return h+[[a,b]]
W=[
E('distribute','/dɪˈstrɪbjuːt/','分配；分发；配送；使分布','把一堆东西拆成份，分别送到不同人或不同地方；重点是从一处到多处。','dis- 分开 + 拉丁 tribuere“给予、分派”，接分词 distribūtus 借入英语。',D,'distribute books to students 是向学生发书；be distributed across an area 是分布在某区域。分配可以均匀，也可以不均匀，distribute 本身不保证每人一样多。','distribute to；distribute among；be widely distributed。','contribute 是把自己的一份投入共同事务；distribute 是把东西分到各处，方向不同。',('Volunteers distributed food to the families.','志愿者向这些家庭分发食物。'),('The sensors are distributed throughout the building.','传感器分布在整栋楼里。')),
E('distribution','/ˌdɪstrɪˈbjuːʃən/','分配；分发；配送；分布','分配这件事，或东西最后落在各处的样子，都可用 distribution。','拉丁 distribūtiō，经法语或拉丁借入；名词在英语有较早独立记录，不能只按现代 distribute + -ion 当成历史。',T+[['拉丁 distribuere → distribūtiō → 法语 distribution','分开给予 → 分配行为'],['英语 distribution','分配、配送及分布形态']],'distribution of food 讲发放；distribution of income 讲收入如何分布。统计的 probability distribution 描述概率如何落到各可能值或范围上，并不是送货过程。','income distribution；a distribution centre；a probability distribution。','delivery 侧重送达；distribution 常涵盖向多处配置或供应的整体。数量相同，分布也可能不同。',('The map shows the distribution of rainfall across the region.','地图显示了该地区降雨的分布。'),('The company opened a new distribution centre.','公司开设了一个新的配送中心。'),sources=['https://www.etymonline.com/word/distribution','https://en.wiktionary.org/wiki/distribution#English']),
E('distributor','英 /dɪˈstrɪbjətə/；美 /dɪˈstrɪbjətər/','经销商；分销商；分配装置','负责把产品从上游分到下游各处的角色，或者执行分配功能的装置。','distribute + -or；动作名词化为执行者。',A(D,'英语 distribute + -or → distributor','分发 → 负责分发的人、公司或装置'),'商业中 distributor 通常从生产方取得货物再供应给其他商家，具体商业角色依合同而定。传统发动机里也有分电器这个义项，因为它分配点火电流。','a regional distributor；an authorised distributor；a film distributor。','manufacturer 制造产品；distributor 组织分销；retailer 通常直接零售给消费者，同一公司也可能兼任几种角色。',('The manufacturer appointed a regional distributor.','制造商指定了一家地区分销商。'),('A film distributor arranged the movie’s release in several countries.','电影发行商安排了这部影片在几个国家上映。')),
E('distributable','/dɪˈstrɪbjʊtəbəl/','可分配的；可分发的','东西不只是存在，还具备可以向别人分出去的条件。','distribute + -able“可以……的”。',A(D,'英语 distribute + -able → distributable','分配 → 可供分配的'),'可修饰文件、物资或金额。distributable profits 是可供分配的利润这个专门说法；普通学习先掌握“可以分出去”，实际条件由相应场景决定。','distributable materials；distributable profits；a distributable package。','distributed 是已经分发；distributable 是可以分发。两个词末尾都长，但表达的阶段不同。',('The team prepared a distributable version of the training materials.','团队准备了一版可以分发的培训资料。'),('Only the approved files are distributable.','只有获准的文件可以分发。')),
E('distributive','/dɪˈstrɪbjətɪv/','分配的；分配性的；分别作用的','原来对着一整组做的动作，可以分到组内各部分去做；这个画面能帮助理解数学分配律。','拉丁 distribūtīvus，经法语 distributif 或拉丁借入；与 distribute 对应的形容词。',T+[['拉丁 distribuere → distribūtīvus；法语 distributif','分配 → 与分配相关的'],['英语 distributive','分配的；分别作用的']],'乘法对加法的分配律是 a(b+c)=ab+ac。distributive justice 则讨论利益、负担怎样分配。两者都涉及“分到各部分”，却是不同学科里的具体概念。','the distributive law；distributive justice；a distributive effect。','distribution 是分配或分布本身；distributive 是修饰这种作用或关系的形容词。不是所有运算都满足分配律。',('The teacher used the distributive law to expand the expression.','老师用分配律展开了这个式子。'),('The seminar examined different accounts of distributive justice.','研讨课考察了关于分配正义的不同观点。')),
E('redistribute','/ˌriːdɪˈstrɪbjuːt/','重新分配；再分发','已经分过一轮，现在把份额或位置重新安排；也可以把拿到的东西继续分发。','re- 再、重新 + distribute。',A(D,'英语 re- + distribute → redistribute','分配 → 再分配、重新分配'),'既可 redistribute tasks 重新分工，也可 redistribute heat 重新分布热量。前缀只表示再安排，不自动说明结果更平均。','redistribute resources；redistribute tasks；redistribute the load。','redistribute 不等于 reproduce“复制”；可以只改变现有东西的去向，总量并没有增加。',('The manager redistributed the tasks after two colleagues left.','两位同事离开后，经理重新分配了任务。'),('The fan helps redistribute warm air through the room.','风扇帮助暖空气在房间里重新分布。')),
E('redistribution','/ˌriːdɪstrɪˈbjuːʃən/','重新分配；再分发','把重新安排份额的过程单独拿出来说，关注什么从哪里转移到了哪里。','re- + distribution；也与 redistribute 的动作对应。',A(D,'英语 distribution；re- + distribution → redistribution','分配格局 → 重新安排这个格局'),'常见 redistribution of resources、redistribution of income；也能说负载或热量重分布。词语本身只描述重新分配，赞成或反对要另外表达。','the redistribution of resources；income redistribution；load redistribution。','distribution 可以是当前分布；redistribution 强调它发生了一轮重新安排。',('The reorganisation involved a redistribution of responsibilities.','这次重组涉及职责的重新分配。'),('The diagram shows the redistribution of heat within the system.','示意图展示了系统内部热量的重新分布。')),
E('attribute','名词 /ˈætrɪbjuːt/；动词 /əˈtrɪbjuːt/','属性；特点；把……归因于；认为出自','把一个特点、结果或作品挂到某个对象名下：它有这个特点，或这件事归到它身上。','ad- 朝向 + tribuere“分派”→ 拉丁 attribuere；名词接 attributum“被赋予的东西”，动词接 attributus。',AT,'attribute A to B 是把 A 归因于 B，或认为 A 出自 B。名词 an attribute of 是某对象的一项特征。两种词性重音不同：名词第一音节，动词第二音节。','attribute success to；be attributed to；a key attribute。','contribute to 是促成；attribute to 是把原因或归属判给。A contributes to B 与 someone attributes B to A 不是同一语法。',('She attributed her progress to regular practice.','她把自己的进步归功于经常练习。'),('Patience is an important attribute of a good teacher.','耐心是好老师的一项重要品质。'),('The painting is attributed to an unknown workshop.','这幅画被认为出自一个身份不明的画坊。'),sources=['https://www.etymonline.com/word/attribute']),
E('attribution','/ˌætrɪˈbjuːʃən/','归因；归属判断；署名说明','把作品交还到作者名下，或把结果的解释交到某个原因名下，这个归属动作就是 attribution。','拉丁 attribūtiō，经法语或拉丁进入英语；与 attribute 相应的独立借词。',T+[['拉丁 attribuere → attribūtiō；法语 attribution','归于 → 归属、指派行为'],['英语 attribution','归因；作者归属或署名']],'艺术研究会讨论 attribution of a painting；资料使用中的 attribution 常指注明作者或出处。心理学的 attribution 则讨论人怎样解释行为原因。','author attribution；causal attribution；provide attribution。','attribution 不等于 copyright“版权”；署名是说明归属，版权涉及另外的权利关系。',('The museum revised the attribution of the painting after new research.','新研究完成后，博物馆修订了这幅画的作者归属。'),('The caption includes a clear attribution to the photographer.','图片说明清楚标明了摄影师。'),sources=['https://www.etymonline.com/word/attribution','https://en.wiktionary.org/wiki/attribution#English']),
E('attributable','/əˈtrɪbjʊtəbəl/','可归因于的；可归于的','某个结果可以有理由地算到某个原因头上，或者某件作品可以归到某位作者名下。','attribute + -able；这里接动词“归于”。',A(AT,'英语 attribute + -able → attributable','归因、归属 → 可以归于的'),'常说 be attributable to。partly attributable to 表示部分归因，并非唯一原因；entirely attributable to 的断言更强。','be attributable to；partly attributable to；directly attributable to。','attractive 是有吸引力，attributable 是可归于；共同的 attr- 开头不代表后面意思相同。',('The delay was partly attributable to bad weather.','延误部分是由恶劣天气造成的。'),('The improvement is attributable to several changes in the process.','改善可以归因于流程中的几项调整。')),
E('contribution','英 /ˌkɒntrɪˈbjuːʃən/；美 /ˌkɑːntrɪˈbjuːʃən/','贡献；捐助；投入的一份；投稿','很多人把自己的一份放进共同的事情里，你放进去的时间、钱、想法或文章都可能是 contribution。','拉丁 con- 一起 + tribuere → contribuere → contribūtiō，经法语和拉丁借入；不是英语先有 contribute 才简单造出的名词。',T+[['拉丁 con- + tribuere → contribuere → contribūtiō','一起交出、汇集 → 共同投入的一份'],['法语 contribution → 英语 contribution','贡献、捐助；后来也指投稿等']],'make a contribution to 中 to 是介词，后可接名词或 -ing。contribution 不一定是捐钱；做实验、提供意见、写一篇文章都可能构成贡献。','make a contribution to；a significant contribution；a voluntary contribution。','donation 常指捐赠；contribution 范围更广，可指参与、成果或文章。',('Her research made a significant contribution to the field.','她的研究为这个领域作出了重要贡献。'),('Each volunteer made a different contribution to the project.','每位志愿者都以不同方式为项目出了力。'),sources=['https://www.etymonline.com/word/contribution']),
E('tribute','/ˈtrɪbjuːt/','致敬；赞颂；贡赋；贡品','原先把一份财物交给上位者，后来也可以把话语、作品或礼物献给值得尊敬的人。','拉丁 tribūtum“交付、支付的东西”，接 tribuere，经法语与拉丁借入。',TB,'pay tribute to 在现代常是表达敬意，并不一定付款。a tribute concert 是致敬音乐会；历史语境中的 tribute 可能是体现臣属关系的贡赋。','pay tribute to；a tribute to；a tribute concert；pay tribute。','tribute 常强调尊敬或历史贡赋；contribution 强调投入共同事务。a tribute to her work 是赞颂，不是她提供的一份贡献。',('The exhibition pays tribute to the artist’s long career.','展览向这位艺术家漫长的创作生涯致敬。'),('The defeated ruler agreed to pay tribute.','战败的统治者同意缴纳贡赋。'),sources=['https://www.etymonline.com/word/tribute']),
E('tributary','英 /ˈtrɪbjətəri/；美 /ˈtrɪbjəteri/','支流；进贡的；纳贡者','一条小河把自己的水送入另一条河，像向更大的系统贡献一份，因此得到“支流”这个意思。','拉丁 tribūtārius，接 tribūtum“贡赋”；先有进贡、提供一份的含义，后用于汇入其他河流的水道。',T+[['拉丁 tribūtum → tribūtārius → 英语 tributary','贡赋 → 纳贡的、提供附属供应的'],['英语的河流用法','向另一水体汇入水量 → 支流']],'常说 a tributary of a river。它说的是水流汇入关系，不是地图上看起来像树枝就一定叫支流；从主河道分出去的水道则是另一种关系。','a tributary of；a major tributary；a tributary state。','tributary 与历史 tribute 的联系是贡献、缴付；与 tribunal“法庭”只是同族不同分支，不能串成法院管理河流。',('Several tributaries join the river before it reaches the city.','这条河到达城市前，有几条支流汇入。'),('The map marks the river and its main tributaries.','地图标出了这条河及其主要支流。'),sources=['https://www.etymonline.com/word/tributary']),
E('retribution','/ˌretrɪˈbjuːʃən/','惩罚；报应；报复性惩罚','把对方做过的事“还回去”；现代通常强调因为先前的过错而受罚。','re- 回 + 拉丁 tribuere“给” → retribuere“偿还”→ retribūtiō，经法语与拉丁借入。',T+[['拉丁 re- + tribuere → retribuere → retribūtiō','给予回来 → 回报、偿还'],['法语 retribution → 英语 retribution','早期可泛指回报；现代多为惩罚或报应']],'in retribution for 表示作为对某事的惩罚或报复。词史上可以回报好事，现代常用义却偏向惩罚，不宜用来谢人帮忙。','fear of retribution；in retribution for；seek retribution。','revenge 常突出个人报复；retribution 常把惩罚呈现为对过错的回应，是否公正仍由说话者与语境决定。',('Several witnesses remained silent for fear of retribution.','几位证人因害怕报复而保持沉默。'),('The story contrasts forgiveness with the desire for retribution.','故事把宽恕与寻求报复的欲望作了对照。'),sources=['https://www.etymonline.com/word/retribution']),
E('tribe','/traɪb/','部族；族群共同体；部落民族；同类群体','把具有共同身份、联系或政治组织的人看成一个共同体；具体组织形态远比“住在一起的一小群人”丰富。','拉丁 tribus，经法语 tribu 或拉丁借入；更早常联系三分结构，但并非完全确定。',TR+[['法语 tribu；拉丁借入 → 中古英语 tribe','群体分组 → 部族、族群共同体'],['现代英语 tribe','具体民族共同体；也有比喻和分类用法']],'在美国 Indigenous 语境中，tribe 可能是当代有自身政治身份的民族共同体，不能直接解释成“原始人群”。称具体群体时以其自称为准。生物分类中 tribe 还可译作“族”，位于科与属之间的层级。','a tribal nation；a member of a tribe；the tribes of ancient Rome。','clan 常偏亲属宗族，tribe 的用法更广且随历史地区变化；不要硬套一条所有社会通用的大小等级。',('The exhibition was developed in collaboration with members of the tribe.','展览由该族群的成员参与合作策划。'),('The historian compared the political roles of the Roman tribes.','历史学者比较了罗马各部族的政治作用。'),sources=['https://www.etymonline.com/word/tribe','https://americanindian.si.edu/nk360/informational/impact-words-tips']),
E('tribal','/ˈtraɪbəl/','部族的；部落民族的；群体阵营性的','把 tribe 的群体关系变成修饰语：它可以描述现实共同体的事务，也可比喻只认自己一派的态度。','拉丁 tribālis 借入；现代可按 tribe + -al 理解。',TR+[['拉丁 tribālis → 英语 tribal','属于 tribus 的 → 部族共同体的']],'tribal government、tribal language 说具体共同体事务，不自带落后意味。政治评论中 tribal loyalties 有时批评阵营忠诚压过独立判断，需与本义区分。','tribal government；tribal identity；tribal loyalties。','tribal 是形容词，tribe 是名词。把一群人的制度称 tribal，并不说明其中每个人都持同样意见。',('The project supports the teaching of tribal languages.','这个项目支持相关部族语言的教学。'),('The discussion became tribal, with each side defending its own camp.','讨论变成了阵营之争，双方各自护着自己一派。'),sources=['https://en.wiktionary.org/wiki/tribal#English','https://americanindian.si.edu/nk360/informational/impact-words-tips']),
E('tribalism','/ˈtraɪbəlɪzəm/','部族认同或组织方式；群体本位；阵营偏执〔比喻〕','“我们属于同一群体”可以带来认同；若进一步变成只护自己人、不问是非，评论里也会用 tribalism。','tribal + -ism，表示组织形态、认同或相关倾向。',A(TR,'英语 tribal → tribalism','群体关系 → 部族认同；后来亦比喻阵营本位'),'民族社会语境可讨论部族联系；现代政治、体育、网络讨论常用来批评过度站队。后一种比喻是对行为的评价，不能反推所有部族社会都如此。','political tribalism；online tribalism；a sense of tribalism。','teamwork 是合作；tribalism 的批评性用法强调维护自己阵营超过对事实、公平的考虑。',('The essay distinguishes cultural belonging from political tribalism.','文章区分了文化归属感与政治上的阵营偏执。'),('Online tribalism made a careful discussion of the evidence difficult.','网络上的阵营对立让人难以细致讨论证据。')),
E('tribesman','/ˈtraɪbzmən/','部族男成员〔复数 tribesmen〕','tribe 指共同体，man 把范围落到其中的男性成员，连接处的 s 属于复合词形式。','tribe + -s- + man；英语复合词。',A(TR,'英语 tribe + -s- + man → tribesman','部族共同体 → 其中的男性成员'),'读历史材料会遇到这个词。现代具体表达常用 member of the tribe 或具体族名，更容易说明身份，也适合不需要突出性别的场景。','a tribesman；fellow tribesmen；a local tribesman。','tribesman 不等于 chief“首领”；它通常只表示成员。复数 man 变 men，写作 tribesmen。',('The old travel account records a conversation with a tribesman.','那篇旧游记记载了与一位部族男成员的谈话。'),('The translator replaced tribesmen with a more precise community name.','译者用更准确的共同体名称替换了 tribesmen。')),
E('tribune','/ˈtrɪbjuːn/','古罗马保民官或军团军官；民众代言者；讲台〔特定语境〕','原本是与部族分组有关的官员称号，后来不同罗马职务用它；“为民众发声的人”的形象又影响了比喻用法。','拉丁 tribūnus 接 tribus；经法语或拉丁借入。讲台等义另接拉丁 tribūnal、意大利 tribuna。',TR+[['拉丁 tribūnus → 英语 tribune','部族相关官员 → 古罗马若干官职；人民代言者'],['并列的建筑词路线：拉丁 tribūnal → 意大利 tribuna → 英语 tribune','官员座台 → 讲台、特定建筑空间']],'tribune of the plebs 是古罗马保民官；military tribune 是军事职官，不是同一职务。报纸名中的 Tribune 往往借“公众代言者”的形象。','a tribune of the plebs；a military tribune；a tribune of the people。','tribunal 是审判机构或审判席；tribune 通常是官职或人物，不是法院的缩写。',('The book explains the role of a tribune of the plebs.','这本书解释了古罗马保民官的作用。'),('Supporters described her as a tribune of ordinary people.','支持者把她称为普通民众的代言人。'),sources=['https://www.etymonline.com/word/tribune','https://en.wiktionary.org/wiki/tribune#English']),
E('tribunal','/traɪˈbjuːnəl/','法庭；审裁机构；审判席','官员坐着作判断的高台，逐渐用来指进行审判或裁决的机构；从座位转向坐在那里的职能。','拉丁 tribūnus“官员”→ tribūnal“官员座台”，经法语或拉丁进入英语。',TR+[['拉丁 tribūnus → tribūnal','官员 → 官员主持事务的座台'],['法语 tribunal → 英语 tribunal','审判席 → 法庭、审裁机构']],'现代常见专门处理某类争议的 tribunal，如 employment tribunal。不同法域中其组成、权限和与 court 的关系不同，词义先抓“负责审理裁决的机构”。','an employment tribunal；an international tribunal；appear before a tribunal。','tribune 常是官职，tribunal 常是机构。并不是见到 tribunal 就能判断它一定比 court 级别低。',('The tribunal heard evidence from both sides.','审裁机构听取了双方证据。'),('The dispute was referred to an independent tribunal.','争议被提交给一个独立的审裁机构。'),sources=['https://www.etymonline.com/word/tribunal','https://www.gov.uk/government/organisations/hm-courts-and-tribunals-service/about']),
E('tribulation','/ˌtrɪbjəˈleɪʃən/','苦难；磨难〔形近异源辨析〕','不是“分配给你的一份”，而是另一幅被压迫、被碾磨的画面：生活的重压让人备受折磨。','来自拉丁 trībulum“脱粒板”，接 terere“磨、擦”，经 tribulāre、trībulātiō 和法语进入；与 tribuere 不是一条词源。',[['另源拉丁 terere → trībulum','磨、擦 → 带齿的脱粒工具'],['拉丁 tribulāre → 教会拉丁 trībulātiō → 古法语 tribulacion','压迫、使受苦 → 苦难'],['英语 tribulation','磨难、困苦']],'常用复数 trials and tribulations 指种种考验与磨难，偏正式或文学，也可稍带夸张地讲日常麻烦。这里收作形近辨析，不归为“分配”词根的后代。','trials and tribulations；endure tribulation；a period of tribulation。','tribute 与 tribulation 虽然开头相似，前者接给予、贡赋，后者接压迫、磨难。别编成贡税太多所以受苦的词源故事。',('The memoir recounts the trials and tribulations of rebuilding a life.','回忆录讲述了重新建立生活时经历的种种磨难。'),('They supported one another through years of tribulation.','他们在多年的困苦中彼此支持。'),sources=['https://www.etymonline.com/word/tribulation']),
]
ROOT=dict(id='C1550',meaning='分派、给予；群体与官职旁支',core='TRIBU = ALLOT; GIVE; ASSIGN',image='面前有一堆东西：分到各人手里是 distribute，把自己的一份交到共同事务里是 contribute，把结果或特点判到某人名下是 attribute。关键不只是“给”，还有“给谁、归谁”。',intro='拉丁 tribuere 表示分派、给予、支付，传统词源常把它与 tribus“部族、群体”相连。tribe、tribune、tribunal 走群体与官职一线；tribute、distribute、attribute 走给予与归属一线。tribus 更早是否与“三”有关未完全确定，不必把罗马三部族的故事当作每个词的确定起点。',forms='tribu- / tribut- 常见于分派词族，-tion 名词的读音常有 /bjuːʃən/。attribute 名词重读第一音节，动词重读第二音节。tribulation 另接“磨、压”词族，本页只作形近辨析。',branches=[['分出去与重新分配','distribute, distribution, distributor, distributable, distributive, redistribute, redistribution'],['汇入共同事务','contribute, contributor, contribution'],['归给原因或作者','attribute, attribution, attributable'],['贡赋、致敬、回报','tribute, tributary, retribution'],['群体与制度','tribe, tribal, tribalism, tribesman, tribune, tribunal'],['形近而异源','tribulation〔不是本族后代〕']],contrasts='contribute 是投入，distribute 是分出，attribute 是归于。tributary 用支流供应水量的比喻，tribunal 接官员座台。tribulation 的苦难来自压迫、磨损的画面，与贡赋不是一条演化链。',practice='The volunteers contributed their time and distributed the supplies. The organisers paid tribute to their contribution and attributed the success to good cooperation.\n\n志愿者投入时间，分发物资。组织者赞扬了他们的贡献，并把成功归功于良好合作。',words=[w['word'] for w in W]+['contribute','contributor'])
